cat >> public/activity.css <<'EOF'

.activity-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: var(--space-5) var(--space-7);
  margin-block-end: var(--space-5);
}

.activity-filters[hidden] {
  display: none;
}

.filter-field {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.filter-field label {
  font: var(--type-label);
  color: var(--text-primary);
}

.filter-field select,
.filter-field input,
.button-secondary {
  font: var(--type-body);
  color: var(--text-primary);
  background: var(--surface-panel);
  border: var(--border-width-hairline) solid var(--border-default);
  border-radius: var(--radius-md);
  padding: var(--space-4) var(--space-5);
  transition: border-color var(--duration-fast) var(--ease-standard);
}

.filter-field select:hover,
.filter-field input:hover,
.button-secondary:hover {
  border-color: var(--border-strong);
}

.filter-field select:focus-visible,
.filter-field input:focus-visible,
.button-secondary:focus-visible {
  outline: var(--border-width-thick) solid var(--border-focus);
  outline-offset: var(--space-1);
}

.filter-field input[aria-invalid] {
  background: var(--danger-subtle);
  border: var(--border-width-thick) solid var(--danger-text);
}

.filter-error {
  flex-basis: 100%;
  margin: 0;
  font: var(--type-body-sm);
  color: var(--danger-text);
}

.filter-error:empty {
  display: none;
}

.filter-status {
  margin-block: 0 var(--space-5);
  font: var(--type-body-sm);
  color: var(--text-secondary);
}

.empty-state {
  padding: var(--space-13) var(--space-6);
  text-align: center;
  color: var(--text-secondary);
}

.empty-state p {
  margin: 0;
}

.empty-state-title {
  font: var(--type-h3);
  color: var(--text-primary);
}

@media (prefers-reduced-motion: reduce) {
  .filter-field select,
  .filter-field input,
  .button-secondary {
    transition: none;
  }
}
EOF
